// SPEC §4.19.3: the manifest-owned launcher text. Split from the plan
// builders (plan.ts) by responsibility: generated bytes here, plan assembly
// there.
// SPEC §4.19.3: the manifest-owned launcher. Plain module syntax
// (imports, no top-level await) so any Node can parse it: node floor
// check, engine resolution at the root or tool dir, in-process main()
// call with CODICTATOR_HOOK=1, and the harness's embedded static block
// reply when no engine exists. The launcher is generated TEXT, not a
// runtime import of this module, so its module specifiers interpolate
// (SPEC §10.3 item 3 scans source for node:fs and friends); the emitted
// bytes are the plain imports below.
function launcherImport(decl: string, module: string): string {
	return `${decl} from "node:${module}";`;
}

export const LAUNCHER_TEXT = [
	"// Generated by `codictator init` (SPEC §4.19.3); do not edit by hand.",
	"// static replies below per configured harness (SPEC §4.5.1) and until then",
	"// they are the two P0 harness deny forms by hand. Zero dependencies and",
	"// ES2015-only syntax, so any Node parses it: the version check runs before",
	"// any newer syntax could load, and only node: built-ins are imported. It",
	"// sets CODICTATOR_HOOK=1 in the engine process, then resolves the engine at",
	"// <root>/node_modules/codictator/dist/cli/main.js else",
	"// <root>/.codictator/tool/node_modules/codictator/dist/cli/main.js. A",
	"// missing engine answers the harness's embedded static CDX-E003 block",
	"// reply; outside hook it prints CDX-E003 and exits 6. Git hooks arrive",
	"// as a `git` first word and route to the engine like hook words do, so",
	"// a missing engine or an old node fails the commit or push closed.",
	"// Version arbitration",
	"// between the root and tool-dir engines (SPEC §4.19 EC-6) belongs to the",
	"// phase 9 CLI: until then the first candidate that exists wins.",
	launcherImport("import { existsSync }", "fs"),
	launcherImport("import path", "path"),
	launcherImport("import { fileURLToPath, pathToFileURL }", "url"),
	"",
	"const MIN_NODE_MAJOR = 24;",
	"",
	"function nodeMajor() {",
	"\tconst match = /^v(\\d+)\\./.exec(process.version);",
	"\tif (match === null) {",
	"\t\treturn 0;",
	"\t}",
	"\tconst major = parseInt(match[1], 10);",
	"\tif (Number.isNaN(major)) {",
	"\t\treturn 0;",
	"\t}",
	"\treturn major;",
	"}",
	"",
	"// The launcher ships at <root>/.codictator/bin/run.mjs, so the repo root",
	"// is three levels up from this file.",
	"function launcherRoot() {",
	"\treturn path.dirname(",
	"\t\tpath.dirname(path.dirname(fileURLToPath(import.meta.url))),",
	"\t);",
	"}",
	"",
	"function engineCandidates(root) {",
	"\treturn [",
	`\t\tpath.join(root, "node_modules", "codictator", "dist", "cli", "main.js"),`,
	"\t\tpath.join(",
	"\t\t\troot,",
	`\t\t\t".codictator",`,
	`\t\t\t"tool",`,
	`\t\t\t"node_modules",`,
	`\t\t\t"codictator",`,
	`\t\t\t"dist",`,
	`\t\t\t"cli",`,
	`\t\t\t"main.js",`,
	"\t\t),",
	"\t];",
	"}",
	"",
	"// The embedded pre-engine deny forms (SPEC §4.5.1): exit 0 with the",
	"// harness's own deny JSON. Answers null for harnesses without a static",
	"// form, so the caller falls back to the process exit code.",
	"function staticReply(harness, code, message) {",
	`\tif (harness === "muse-code") {`,
	"\t\treturn {",
	"\t\t\texitCode: 0,",
	"\t\t\tstdout: JSON.stringify({",
	"\t\t\t\thookSpecificOutput: {",
	`\t\t\t\t\thookEventName: "PreToolUse",`,
	`\t\t\t\t\tpermissionDecision: "deny",`,
	`\t\t\t\t\tpermissionDecisionReason: \`\${code} \${message}\`,`,
	"\t\t\t\t},",
	"\t\t\t}),",
	"\t\t};",
	"\t}",
	`\tif (harness === "opencode") {`,
	"\t\treturn {",
	"\t\t\texitCode: 0,",
	"\t\t\tstdout: JSON.stringify({",
	`\t\t\t\tdecision: "block",`,
	`\t\t\t\tmessage: \`\${code} \${message}\`,`,
	`\t\t\t\teventId: "static",`,
	"\t\t\t}),",
	"\t\t};",
	"\t}",
	"\treturn null;",
	"}",
	"",
	"function writeStatic(reply) {",
	"\tprocess.stdout.write(reply.stdout);",
	"\tprocess.exitCode = reply.exitCode;",
	"}",
	"",
	"function writeMissingEngine() {",
	"\tprocess.stderr.write(",
	`\t\t"CDX-E003 codictator engine is not installed; run npm ci, then retry.\\n",`,
	"\t);",
	"\tprocess.exitCode = 6;",
	"}",
	"",
	"function writeOldNode() {",
	"\tprocess.stderr.write(",
	`\t\t\`CDX-E002 node \${process.version} is older than the required >=24.0.0; install a newer Node, then retry.\\n\`,`,
	"\t);",
	"\tprocess.exitCode = 6;",
	"}",
	"",
	"function writeEngineFailed() {",
	"\tprocess.stderr.write(",
	`\t\t"CDX-E901 the codictator engine failed to load; the tool call is blocked.\\n",`,
	"\t);",
	"\tprocess.exitCode = 1;",
	"}",
	"",
	"function oldNodeMessage() {",
	"\treturn (",
	`\t\t\`node \${process.version} is older than the required >=24.0.0; \` +`,
	`\t\t"install a newer Node, then retry the tool call."`,
	"\t);",
	"}",
	"",
	"function firstExisting(candidates) {",
	"\tfor (let index = 0; index < candidates.length; index += 1) {",
	"\t\tif (existsSync(candidates[index])) {",
	"\t\t\treturn candidates[index];",
	"\t\t}",
	"\t}",
	"\treturn null;",
	"}",
	"",
	"function reportMissing(harness) {",
	"\tconst missing = staticReply(",
	"\t\tharness,",
	`\t\t\t"CDX-E003",`,
	`\t\t\t"codictator engine is not installed; run npm ci, then retry the tool call.",`,
	"\t);",
	"\tif (missing === null) {",
	"\t\twriteMissingEngine();",
	"\t\treturn;",
	"\t}",
	"\twriteStatic(missing);",
	"}",
	"",
	"function checkNode(harness) {",
	"\tif (nodeMajor() < MIN_NODE_MAJOR) {",
	`\t\tconst oldNode = staticReply(harness, "CDX-E002", oldNodeMessage());`,
	"\t\tif (oldNode === null) {",
	"\t\t\twriteOldNode();",
	"\t\t\treturn false;",
	"\t\t}",
	"\t\twriteStatic(oldNode);",
	"\t\treturn false;",
	"\t}",
	"\treturn true;",
	"}",
	"",
	"function runEngine(enginePath, args, harness) {",
	`\tprocess.env.CODICTATOR_HOOK = "1";`,
	"\timport(pathToFileURL(enginePath).href)",
	"\t\t.then(",
	"\t\t\t(engine) => {",
	`\t\t\t\tif (engine === null || typeof engine.main !== "function") {`,
	`\t\t\t\t\tthrow new Error("engine entry has no main");`,
	"\t\t\t\t}",
	"\t\t\t\treturn engine.main(args, process.cwd());",
	"\t\t\t},",
	"\t\t\t(error) => {",
	"\t\t\t\tthrow error;",
	"\t\t\t},",
	"\t\t)",
	"\t\t.then(",
	"\t\t\t(code) => {",
	`\t\t\t\tprocess.exitCode = typeof code === "number" ? code : 0;`,
	"\t\t\t},",
	"\t\t\t() => {",
	"\t\t\t\tconst failed = staticReply(",
	"\t\t\t\t\tharness,",
	`\t\t\t\t\t"CDX-E901",`,
	`\t\t\t\t\t"the codictator engine failed to load; the tool call is blocked.",`,
	"\t\t\t\t);",
	"\t\t\t\tif (failed === null) {",
	"\t\t\t\t\twriteEngineFailed();",
	"\t\t\t\t\treturn;",
	"\t\t\t\t}",
	"\t\t\t\twriteStatic(failed);",
	"\t\t\t},",
	"\t\t);",
	"}",
	"",
	"function main() {",
	"\tconst args = process.argv.slice(2);",
	`\tif (args[0] !== "hook" && args[0] !== "git") {`,
	"\t\twriteMissingEngine();",
	"\t\treturn;",
	"\t}",
	`\tconst harness = args[1] || "";`,
	"\tif (!checkNode(harness)) {",
	"\t\treturn;",
	"\t}",
	"\tconst enginePath = firstExisting(engineCandidates(launcherRoot()));",
	"\tif (enginePath === null) {",
	"\t\treportMissing(harness);",
	"\t\treturn;",
	"\t}",
	"\trunEngine(enginePath, args, harness);",
	"}",
	"main();",
	"",
].join("\n");
